/* ============================================================
   05c — ГОСПОДИН ЦВЕТОВ (LORD OF FLOWERS)
   Пользовательская МУЗЫКА атаки и войсклипы Flowery встроены в билд
   (base64), играются через ту же WebAudio-шину, что и прочие звуки
   (с учётом громкости SFX/музыки).
   ============================================================ */
const FLOWER_MUSIC_MP3 = 'data:audio/mpeg;base64,';

const FLOWER_VOICE_POWERS = 'data:audio/ogg;base64,';
const FLOWER_VOICE_LAST = 'data:audio/ogg;base64,';
const FLOWER_VOICE_HEH = 'data:audio/ogg;base64,';
const FLOWER_VOICE_1 = 'data:audio/ogg;base64,';
const FLOWER_VOICE_2 = 'data:audio/ogg;base64,';
const FLOWER_VOICE_3 = 'data:audio/ogg;base64,';
const FLOWER_VOICE_4 = 'data:audio/ogg;base64,';

const FLOWER_VOICE_LIST = [FLOWER_VOICE_1, FLOWER_VOICE_2, FLOWER_VOICE_3, FLOWER_VOICE_4, FLOWER_VOICE_HEH];

/* ---- декодирование встроенных сэмплов (каждый — один раз) ---- */
function _flowerToU8(dataUrl) {
  const b = atob(dataUrl.split(',')[1]);
  const n = b.length, u8 = new Uint8Array(n);
  for (let i = 0; i < n; i++) u8[i] = b.charCodeAt(i);
  return u8;
}
Audio3D_SFX._flowerBufs = {};
Audio3D_SFX._flowerDecoding = {};
/* Возвращает AudioBuffer или null (декодирование асинхронное). */
Audio3D_SFX.flowerBuffer = function (key, dataUrl, onReady) {
  if (this._flowerBufs[key]) return this._flowerBufs[key];
  if (this._flowerDecoding[key] || !this.ctx) return null;
  this._flowerDecoding[key] = true;
  const self = this;
  try {
    const u8 = _flowerToU8(dataUrl);
    const done = (buf) => { self._flowerBufs[key] = buf; if (onReady) onReady(buf); };
    const p = this.ctx.decodeAudioData(u8.buffer, done, () => { });
    if (p && p.then) p.then(done).catch(() => { });
  } catch (e) { }
  return null;
};

/* МУЗЫКА АТАКИ: короткий фрагмент играет поверх боя на канале музыки,
   пока идёт ульта/фанфара. */
Audio3D_SFX.flowerMusic = function () {
  if (!this.ctx || this.muted || this.musicOff) return false;
  const self = this;
  const fire = () => {
    const buf = self.flowerBuffer('music', FLOWER_MUSIC_MP3, null);
    if (!buf) return false;
    if (self._flowerMusicSrc) { try { self._flowerMusicSrc.stop(); } catch (e) { } }
    const src = self.ctx.createBufferSource();
    src.buffer = buf;
    const g = self.ctx.createGain();
    g.gain.value = 0.85;
    src.connect(g);
    g.connect(self.musicBus || self.sfx);
    src.onended = () => { if (self._flowerMusicSrc === src) self._flowerMusicSrc = null; };
    self._flowerMusicSrc = src;
    self._flowerMusicGain = g;
    src.start();
    return true;
  };
  if (!fire()) {
    const iv = setInterval(() => { if (fire()) clearInterval(iv); }, 60);
    setTimeout(() => clearInterval(iv), 4000);
  }
  return true;
};
Audio3D_SFX.flowerMusicStop = function () {
  if (this._flowerMusicSrc) { try { this._flowerMusicSrc.stop(); } catch (e) { } this._flowerMusicSrc = null; }
};

/* ГОЛОС: реплика Флауэра (непозиционная — кинематографично, у экрана). */
Audio3D_SFX.flowerVoice = function (which, gain) {
  if (!this.ctx || this.muted) return false;
  const dataUrl = which || FLOWER_VOICE_LIST[(Math.random() * FLOWER_VOICE_LIST.length) | 0];
  const key = 'v' + dataUrl.length;
  const self = this;
  const fire = () => {
    const buf = self.flowerBuffer(key, dataUrl, null);
    if (!buf) return false;
    const src = self.ctx.createBufferSource();
    src.buffer = buf;
    const g = self.ctx.createGain();
    g.gain.value = gain === undefined ? 0.95 : gain;
    src.connect(g); g.connect(self.sfx);
    src.start();
    return true;
  };
  if (!fire()) {
    const iv = setInterval(() => { if (fire()) clearInterval(iv); }, 40);
    setTimeout(() => clearInterval(iv), 4000);
  }
  return true;
};
